namespace TutorFlow.Api.Http;

/// <summary>
/// Mapeo central de errores tipados a respuestas (SPEC 3.3, AGENTS 5). No se traga ningun error: cada rama
/// responde y deja un log sin datos academicos; el 500 no filtra detalles internos.
/// </summary>
public sealed class ErrorHandlingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ErrorHandlingMiddleware> _logger;

    public ErrorHandlingMiddleware(RequestDelegate next, ILogger<ErrorHandlingMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            await _next(context);
        }
        catch (Exception) when (context.Response.HasStarted)
        {
            throw;
        }
        catch (OperationCanceledException) when (context.RequestAborted.IsCancellationRequested)
        {
            // El cliente cancelo: no hay a quien responder.
        }
        catch (IdentidadInvalidaException ex)
        {
            _logger.LogInformation("Identidad rechazada por L1 (motivo: {Motivo}).", ex.Motivo);
            context.RequestServices.GetService<IContextoAuditoria>()?.Denegar("identidad");
            await Responder403(context, Respuestas.Identidad());
        }
        catch (AccesoDenegadoException ex)
        {
            _logger.LogInformation("Acceso denegado (motivo: {Motivo}).", ex.Motivo);
            context.RequestServices.GetService<IContextoAuditoria>()?.Denegar(ex.Motivo);
            await Responder403(context, Respuestas.Acceso(ex.Rol, ex.Tokens, ex.CostoUsd));
        }
        catch (DependenciaNoDisponibleException)
        {
            _logger.LogWarning("Dependencia no disponible.");
            await Problema(context, 503, "Servicio no disponible", "Una dependencia necesaria no esta disponible. Intenta de nuevo mas tarde.");
        }
        catch (DatoAcademicoInvalidoException)
        {
            _logger.LogError("La fuente de datos devolvio un dato invalido.");
            await Problema(context, 503, "Servicio no disponible", "Una dependencia necesaria devolvio datos invalidos. Intenta de nuevo mas tarde.");
        }
        catch (PendienteDeIntegracionException)
        {
            await Problema(context, 503, "Funcionalidad pendiente de integracion", "El flujo posterior a la validacion de identidad y del roster aun esta pendiente de integracion.");
        }
        catch (Exception ex)
        {
            // Se registra el tipo para operacion; el cliente solo recibe el requestId.
            _logger.LogError("Error no controlado ({TipoError}).", ex.GetType().Name);
            await Problema(context, 500, "Error interno", "Ocurrio un error interno. Reporta el identificador de la peticion.");
        }
    }

    private static Task Responder403(HttpContext context, Contracts.PreguntarResponse cuerpo)
    {
        context.Response.Clear();
        context.Response.Headers[RequestIdMiddleware.HeaderName] = RequestIdMiddleware.Obtener(context);
        return Respuestas.EscribirJsonAsync(context.Response, StatusCodes.Status403Forbidden, cuerpo);
    }

    private static Task Problema(HttpContext context, int status, string titulo, string detalle)
    {
        context.Response.Clear();
        var id = RequestIdMiddleware.Obtener(context);
        context.Response.Headers[RequestIdMiddleware.HeaderName] = id;
        return Respuestas.EscribirProblemaAsync(context.Response, status, titulo, detalle, id);
    }
}
using System.Diagnostics;
using TutorFlow.Application.Audit;
using TutorFlow.Application.Ports;

namespace TutorFlow.Api.Http;

/// <summary>
/// Emite EXACTAMENTE UN evento <c>pregunta</c> (SPEC 9.1) por cada <c>POST /api/asistente/preguntar</c>, sea cual sea el
/// resultado (200, 400, 403, 5xx). Va por fuera del middleware de errores: el estado ya es el definitivo cuando la
/// respuesta empieza (<c>OnStarting</c>); si nunca empieza (cancelacion, excepcion), se emite al terminar. Un fallo al
/// auditar jamas altera la respuesta.
/// </summary>
public sealed class AuditoriaMiddleware
{
    public const string RutaPreguntar = "/api/asistente/preguntar";
    private const int EstadoClienteCancelo = 499;

    private readonly RequestDelegate _next;
    private readonly ILogger<AuditoriaMiddleware> _logger;

    public AuditoriaMiddleware(RequestDelegate next, ILogger<AuditoriaMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        if (!HttpMethods.IsPost(context.Request.Method)
            || !string.Equals(context.Request.Path.Value?.TrimEnd('/'), RutaPreguntar, StringComparison.OrdinalIgnoreCase))
        {
            await _next(context);
            return;
        }

        var cronometro = Stopwatch.StartNew();
        var servicios = context.RequestServices;
        var contexto = servicios.GetRequiredService<IContextoAuditoria>();
        var requestId = RequestIdMiddleware.Obtener(context);

        context.Response.OnStarting(() => EmitirAsync(context, contexto, requestId, cronometro, context.Response.StatusCode));
        try
        {
            await _next(context);
        }
        finally
        {
            var estado = context.Response.HasStarted
                ? context.Response.StatusCode
                : context.RequestAborted.IsCancellationRequested ? EstadoClienteCancelo : context.Response.StatusCode;
            await EmitirAsync(context, contexto, requestId, cronometro, estado);
        }
    }

    private async Task EmitirAsync(HttpContext context, IContextoAuditoria contexto, string requestId, Stopwatch cronometro, int estado)
    {
        try
        {
            var reloj = context.RequestServices.GetRequiredService<IClock>();
            var evento = contexto.ConstruirUnaVez(requestId, reloj.UtcNow, estado, cronometro.ElapsedMilliseconds);
            if (evento is not null)
            {
                await context.RequestServices.GetRequiredService<IAuditLog>().RegistrarPreguntaAsync(evento, CancellationToken.None);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError("No se pudo registrar el evento de auditoria ({TipoError}).", ex.GetType().Name);
        }
    }
}

using TutorFlow.Application.Ports;

namespace TutorFlow.Application.Audit;

/// <inheritdoc />
public sealed class ContextoAuditoria : IContextoAuditoria
{
    private const int MaxPregunta = 1000;
    private const int MaxCampo = 64;

    private readonly object _lock = new();
    private readonly List<string> _estudiantes = [];
    private readonly List<string> _programas = [];
    private readonly List<string> _denegados = [];
    private readonly List<HerramientaAuditada> _herramientas = [];
    private readonly List<string> _citas = [];
    private string _pregunta = string.Empty;
    private UsuarioAuditado? _usuario;
    private bool _identidadValida;
    private string? _motivo;
    private string? _estrategia;
    private string? _modelo;
    private int _tokens;
    private decimal _costo;
    private bool _emitido;

    public void Iniciar(string pregunta, string? rol, string? id)
    {
        lock (_lock)
        {
            _pregunta = pregunta ?? string.Empty;
            _usuario = rol is not null && id is not null ? new UsuarioAuditado(Acotar(rol), Acotar(id)) : null;
        }
    }

    public void IdentidadValidada()
    {
        lock (_lock)
        {
            _identidadValida = true;
        }
    }

    public void ObjetivosDenegados(IEnumerable<string> objetivos)
    {
        ArgumentNullException.ThrowIfNull(objetivos);
        lock (_lock)
        {
            foreach (var o in objetivos)
            {
                Agregar(_denegados, Acotar(o));
            }
        }
    }

    public void Denegar(string motivo)
    {
        lock (_lock)
        {
            _motivo ??= motivo;
        }
    }

    public void HerramientaDenegada(string nombre, string? objetivo)
    {
        lock (_lock)
        {
            _herramientas.Add(new HerramientaAuditada(Acotar(nombre), objetivo is null ? null : Acotar(objetivo), "denegado"));
        }
    }

    public void ConsultaExitosa(string nombre, string objetivo, bool esPrograma)
    {
        lock (_lock)
        {
            _herramientas.Add(new HerramientaAuditada(Acotar(nombre), objetivo, "permitido"));
            if (esPrograma)
            {
                foreach (var p in objetivo.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
                {
                    Agregar(_programas, p);
                }
            }
            else
            {
                Agregar(_estudiantes, objetivo);
            }
        }
    }

    public void FlujoLlm(IEnumerable<string>? citas = null, string? estrategia = null, string? modelo = null, int? tokens = null, decimal? costoUsd = null)
    {
        lock (_lock)
        {
            if (citas is not null)
            {
                foreach (var c in citas)
                {
                    Agregar(_citas, c);
                }
            }

            _estrategia = estrategia ?? _estrategia;
            _modelo = modelo ?? _modelo;
            _tokens = tokens ?? _tokens;
            _costo = costoUsd ?? _costo;
        }
    }

    public EventoPregunta? ConstruirUnaVez(string requestId, DateTimeOffset ts, int resultado, long latenciaMs)
    {
        lock (_lock)
        {
            if (_emitido)
            {
                return null;
            }

            _emitido = true;
            var pregunta = _pregunta.Length > MaxPregunta ? _pregunta[..MaxPregunta] : _pregunta;
            return new EventoPregunta(
                ts,
                requestId,
                _usuario,
                _identidadValida,
                pregunta,
                _estudiantes.ToArray(),
                _programas.ToArray(),
                _herramientas.ToArray(),
                resultado,
                _motivo,
                _citas.ToArray(),
                _estrategia,
                _modelo,
                _tokens,
                _costo,
                latenciaMs,
                _denegados.ToArray());
        }
    }

    private static void Agregar(List<string> lista, string valor)
    {
        if (!lista.Contains(valor, StringComparer.Ordinal))
        {
            lista.Add(valor);
        }
    }

    /// <summary>Acota campos que vienen del cliente (rol e id declarados) para que no inflen el log.</summary>
    private static string Acotar(string valor) => valor.Length > MaxCampo ? valor[..MaxCampo] : valor;
}
using TutorFlow.Application.Ports;

namespace TutorFlow.Application.Audit;

/// <summary>
/// Contexto de auditoria de UNA peticion (scoped, SPEC 9.2). L1, L2, el despachador y el middleware de errores
/// acumulan aqui; el middleware de auditoria emite el evento una sola vez al terminar. Solo guarda ids, nombres de
/// herramienta y decisiones: nunca notas, respuestas ni datos de la API.
/// </summary>
public interface IContextoAuditoria
{
    /// <summary>Pregunta literal y usuario declarado (si es legible). La identidad aun no esta validada.</summary>
    void Iniciar(string pregunta, string? rol, string? id);

    /// <summary>L1 supero la validacion de consistencia.</summary>
    void IdentidadValidada();

    /// <summary>Objetivos intentados y denegados por una guardia (L2): no son consultas ejecutadas.</summary>
    void ObjetivosDenegados(IEnumerable<string> objetivos);

    /// <summary>Motivo de denegacion: identidad, referencia, herramienta, politica o salida (el primero gana).</summary>
    void Denegar(string motivo);

    /// <summary>Invocacion de herramienta denegada (objetivo intentado, sin datos).</summary>
    void HerramientaDenegada(string nombre, string? objetivo);

    /// <summary>
    /// Consulta academica ejecutada con exito: el objetivo entra a estudiantesConsultados o, si es de programa
    /// (ids separados por coma), a programasConsultados.
    /// </summary>
    void ConsultaExitosa(string nombre, string objetivo, bool esPrograma);

    /// <summary>Datos del flujo LLM (se completan en T-08).</summary>
    void FlujoLlm(IEnumerable<string>? citas = null, string? estrategia = null, string? modelo = null, int? tokens = null, decimal? costoUsd = null);

    /// <summary>Construye el evento y marca la emision: devuelve null si ya se emitio.</summary>
    EventoPregunta? ConstruirUnaVez(string requestId, DateTimeOffset ts, int resultado, long latenciaMs);
}
using System.Text.Json;

namespace TutorFlow.Application.Ports;

/// <summary>Definicion de herramienta que ve el LLM (esquema JSON de sus argumentos).</summary>
public sealed record ToolDefinition(string Nombre, string Descripcion, JsonElement EsquemaArgumentos);

/// <summary>Propuesta de invocacion hecha por el LLM. Es solo una propuesta: el despachador la valida y autoriza.</summary>
public sealed record InvocacionPropuesta(string? Id, string Nombre, JsonElement Argumentos);

public enum RolMensaje
{
    Usuario,
    Asistente,
    Herramienta,
}

public sealed record LlmMensaje(
    RolMensaje Rol,
    string Contenido,
    string? InvocacionId = null,
    string? NombreHerramienta = null);

public sealed record LlmRequest(
    string Sistema,
    IReadOnlyList<LlmMensaje> Mensajes,
    IReadOnlyList<ToolDefinition> Herramientas,
    int MaxTokens);

public sealed record UsoTokens(int Entrada, int Salida);

public sealed record LlmResponse(
    string Texto,
    IReadOnlyList<InvocacionPropuesta> Invocaciones,
    UsoTokens Uso);

/// <summary>Puerto del proveedor LLM. Su salida es texto o propuestas; nunca decide permisos.</summary>
public interface ILlmClient
{
    Task<LlmResponse> CompletarAsync(LlmRequest solicitud, CancellationToken ct);
}

public interface IEmbeddingClient
{
    Task<IReadOnlyList<float[]>> VectorizarAsync(IReadOnlyList<string> textos, CancellationToken ct);
}
namespace TutorFlow.Application.Ports;

public sealed record Fragmento(string ChunkId, string Documento, string Seccion, string Texto);

/// <summary>Recuperacion documental del reglamento. Los fragmentos son datos no confiables.</summary>
public interface IRetriever
{
    Task<IReadOnlyList<Fragmento>> RecuperarAsync(string pregunta, CancellationToken ct);
}
using TutorFlow.Domain.Authorization;

namespace TutorFlow.Application.Ports;

public sealed record CitaDocumental(string Documento, string Seccion);

/// <summary>Resultado ya calculado por el dominio (JSON con formato invariante) y sus citas deterministas (SPEC 7.5).</summary>
public sealed record ResultadoHerramienta(
    string Contenido,
    IReadOnlyList<CitaDocumental> Citas,
    bool UsoDatosEstudiante,
    string? Objetivo);

/// <summary>
/// Unica via de ejecucion de herramientas para el bucle del LLM: L3 (herramienta expuesta) -> esquema -> L4
/// (IAuthorizationPolicy antes de leer) -> ejecucion. El principal lo aporta el servidor, jamas el LLM; una
/// denegacion lanza AccesoDenegadoException y aborta la peticion.
/// </summary>
public interface IToolDispatcher
{
    IReadOnlyList<ToolDefinition> HerramientasExpuestas(PrincipalAcademico principal);

    Task<ResultadoHerramienta> DespacharAsync(
        PrincipalAcademico principal,
        InvocacionPropuesta invocacion,
        CancellationToken ct);
}
using TutorFlow.Application.Ports;
using TutorFlow.Domain.Authorization;

namespace TutorFlow.Application.Llm;

/// <summary>
/// Resultado de la generacion fundamentada, ya validado (SPEC 7.4-7.5). Las citas solo son chunks recuperados en la
/// peticion y las citas deterministas de las herramientas; <see cref="Citas"/> vacia implica texto de abstencion.
/// </summary>
public sealed record RespuestaGenerada(
    string Respuesta,
    IReadOnlyList<CitaDocumental> Citas,
    bool UsoDatosEstudiante,
    int Tokens,
    decimal CostoUsd,
    IReadOnlyList<string> ObjetivosConsultados,
    bool Abstuvo);

/// <summary>
/// Servicio que Core invoca (T-08) despues de L1/L2 y de la recuperacion. Solo propone invocaciones: las ejecuta el
/// <see cref="IToolDispatcher"/>, cuyas excepciones (AccesoDenegadoException, etc.) se propagan sin capturar.
/// Puede lanzar <see cref="LlmNoDisponibleException"/> (Core: 503).
/// </summary>
public interface IGeneradorRespuesta
{
    Task<RespuestaGenerada> GenerarAsync(
        PrincipalAcademico principal,
        string pregunta,
        IReadOnlyList<Fragmento> fragmentos,
        IToolDispatcher herramientas,
        CancellationToken ct);
}
namespace TutorFlow.Application.Llm;

/// <summary>
/// El proveedor LLM no esta disponible o rechazo la credencial (401/403, reintentos agotados, salida ilegible).
/// Core la mapea a 503 (SPEC 10.2). El mensaje nunca contiene la llave ni el cuerpo del proveedor.
/// </summary>
public sealed class LlmNoDisponibleException : Exception
{
    public LlmNoDisponibleException(string message, int? statusCode = null, Exception? inner = null)
        : base(message, inner)
    {
        StatusCode = statusCode;
    }

    /// <summary>Ultimo codigo HTTP del proveedor, si lo hubo.</summary>
    public int? StatusCode { get; }
}

/// <summary>Configuracion LLM invalida (p. ej. LLM_PROVIDER desconocido). Debe fallar al arrancar.</summary>
public sealed class LlmConfiguracionException(string message) : InvalidOperationException(message);
using TutorFlow.Domain.Authorization;

namespace TutorFlow.Application.Errores;

/// <summary>
/// Una capa determinista (L2a, L2b, L3, L4 o L5) denego el acceso: 403-acceso (SPEC 3.4). Aborta toda la peticion.
/// Lleva el rol (para elegir el mensaje) y el motivo de auditoria; tokens y costo reflejan lo consumido antes del rechazo.
/// </summary>
public sealed class AccesoDenegadoException : Exception
{
    public AccesoDenegadoException(RolAcademico rol, string motivo, int tokens = 0, decimal costoUsd = 0m)
        : base(motivo)
    {
        Rol = rol;
        Motivo = motivo;
        Tokens = tokens;
        CostoUsd = costoUsd;
    }

    public RolAcademico Rol { get; }

    /// <summary>Motivo de auditoria: referencia, herramienta, politica o salida.</summary>
    public string Motivo { get; }

    public int Tokens { get; }

    public decimal CostoUsd { get; }
}
namespace TutorFlow.Application.Errores;

/// <summary>
/// La API simulada o el roster no estan disponibles (timeout, 5xx, red, reintentos agotados, roster ausente o vencido).
/// Fail-closed: quien la captura responde 503 (SPEC 3.4, 6.6).
/// </summary>
public sealed class DependenciaNoDisponibleException : Exception
{
    public DependenciaNoDisponibleException(string message)
        : base(message)
    {
    }

    public DependenciaNoDisponibleException(string message, Exception innerException)
        : base(message, innerException)
    {
    }
}
namespace TutorFlow.Application.Errores;

/// <summary>
/// La identidad declarada no supera la validacion de consistencia de L1 (SPEC 3.3 regla 5). El motivo concreto es
/// solo para la auditoria: el cuerpo 403-identidad es identico para todos los motivos (SPEC 3.4).
/// </summary>
public sealed class IdentidadInvalidaException : Exception
{
    public IdentidadInvalidaException(string motivo)
        : base(motivo)
    {
        Motivo = motivo;
    }

    /// <summary>Motivo interno (nunca se devuelve al cliente).</summary>
    public string Motivo { get; }
}
