/// <summary>
/// Base de los adaptadores HTTP: timeout de 20 s por intento, 2 reintentos ante 429/5xx/red respetando retry-after,
/// sin reintento ante 401/403. La llave solo viaja en la cabecera; nunca en logs ni en excepciones.
/// El HttpClient lo aporta Infrastructure (o las pruebas con respuestas grabadas).
/// </summary>
public abstract class HttpLlmClientBase : ILlmClient
{
    public const int MaxReintentos = 2;
    public static readonly TimeSpan TimeoutPorIntento = TimeSpan.FromSeconds(20);
    public static readonly TimeSpan TopeRetryAfter = TimeSpan.FromSeconds(10);

    private readonly HttpClient _http;
    private readonly Action<string>? _log;
    private readonly Func<TimeSpan, CancellationToken, Task> _delay;

    protected HttpLlmClientBase(
        HttpClient http,
        LlmOptions options,
        Action<string>? log = null,
        Func<TimeSpan, CancellationToken, Task>? delay = null)
    {
        _http = http ?? throw new ArgumentNullException(nameof(http));
        Options = options ?? throw new ArgumentNullException(nameof(options));
        _log = log;
        _delay = delay ?? Task.Delay;
    }

    protected LlmOptions Options { get; }

    protected abstract string Endpoint { get; }

    protected abstract string BuildBody(LlmRequest solicitud);

    protected abstract void ApplyAuth(HttpRequestMessage request, string apiKey);

    protected abstract LlmResponse ParseResponse(string json);

    public async Task<LlmResponse> CompletarAsync(LlmRequest solicitud, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(solicitud);
        if (string.IsNullOrWhiteSpace(Options.ApiKey))
        {
            _log?.Invoke("Configuracion LLM: LLM_API_KEY no esta definida.");
            throw new LlmNoDisponibleException("LLM_API_KEY no esta configurada.");
        }

        var body = BuildBody(solicitud);
        int? ultimoEstado = null;
        for (var intento = 0; intento <= MaxReintentos; intento++)
        {
            TimeSpan? retryAfter = null;
            try
            {
                using var request = new HttpRequestMessage(HttpMethod.Post, Endpoint)
                {
                    Content = new StringContent(body, Encoding.UTF8, "application/json"),
                };
                ApplyAuth(request, Options.ApiKey);
                using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
                cts.CancelAfter(TimeoutPorIntento);
                using var response = await _http.SendAsync(request, cts.Token).ConfigureAwait(false);
                var status = (int)response.StatusCode;
                ultimoEstado = status;
                var texto = await response.Content.ReadAsStringAsync(cts.Token).ConfigureAwait(false);

                if (response.IsSuccessStatusCode)
                {
                    try
                    {
                        return ParseResponse(texto);
                    }
                    catch (Exception ex) when (ex is JsonException or InvalidOperationException or KeyNotFoundException or FormatException)
                    {
                        throw new LlmNoDisponibleException($"Respuesta ilegible del proveedor '{Options.Provider}'.", status, ex);
                    }
                }

                if (response.StatusCode is HttpStatusCode.Unauthorized or HttpStatusCode.Forbidden)
                {
                    _log?.Invoke($"Error de configuracion LLM: el proveedor '{Options.Provider}' rechazo la credencial (HTTP {status}).");
                    throw new LlmNoDisponibleException($"El proveedor '{Options.Provider}' rechazo la credencial (HTTP {status}).", status);
                }

                if (status != 429 && status < 500)
                {
                    _log?.Invoke($"El proveedor '{Options.Provider}' rechazo la solicitud (HTTP {status}).");
                    throw new LlmNoDisponibleException($"El proveedor '{Options.Provider}' rechazo la solicitud (HTTP {status}).", status);
                }

                retryAfter = LeerRetryAfter(response.Headers);
            }
            catch (OperationCanceledException) when (ct.IsCancellationRequested)
            {
                throw;
            }
            catch (OperationCanceledException)
            {
                ultimoEstado = null;
                _log?.Invoke($"Timeout de {TimeoutPorIntento.TotalSeconds:0} s del proveedor '{Options.Provider}'.");
            }
            catch (HttpRequestException)
            {
                ultimoEstado = null;
                _log?.Invoke($"Fallo de red hacia el proveedor '{Options.Provider}'.");
            }

            if (intento < MaxReintentos)
            {
                var espera = retryAfter ?? TimeSpan.FromMilliseconds(500 * (intento + 1));
                _log?.Invoke($"Reintento {intento + 1}/{MaxReintentos} del proveedor '{Options.Provider}' en {espera.TotalSeconds:0.###} s.");
                await _delay(espera, ct).ConfigureAwait(false);
            }
        }

        throw new LlmNoDisponibleException(
            $"El proveedor '{Options.Provider}' no respondio tras {MaxReintentos + 1} intentos.",
            ultimoEstado);
    }

    private static TimeSpan? LeerRetryAfter(HttpResponseHeaders headers)
    {
        var ra = headers.RetryAfter;
        if (ra is null)
        {
            return null;
        }

        TimeSpan? valor = ra.Delta ?? (ra.Date is { } d ? d - DateTimeOffset.UtcNow : null);
        if (valor is null)
        {

        // Regla 1: la raiz debe ser un objeto.
        if (raiz.ValueKind != JsonValueKind.Object)
        {
            return LecturaCuerpo.Falla("La raiz del cuerpo debe ser un objeto JSON.");
        }

        // Regla 2: propiedades duplicadas en la raiz o en `usuario`.
        if (TieneDuplicados(raiz))
        {
            return LecturaCuerpo.Falla("El cuerpo contiene propiedades duplicadas.");
        }

        var tieneUsuario = raiz.TryGetProperty("usuario", out var usuario);
        if (tieneUsuario && usuario.ValueKind == JsonValueKind.Object && TieneDuplicados(usuario))
        {
            return LecturaCuerpo.Falla("El cuerpo contiene propiedades duplicadas.");
        }

        // Regla 3: pregunta string, no vacia ni solo espacios, de a lo sumo 1000 caracteres.
        if (!raiz.TryGetProperty("pregunta", out var preguntaEl) || preguntaEl.ValueKind != JsonValueKind.String)
        {
            return LecturaCuerpo.Falla("La propiedad 'pregunta' es obligatoria y debe ser un texto.");
        }

        string? pregunta;
        try
        {
            pregunta = preguntaEl.GetString();
        }
        catch (InvalidOperationException)
        {
            return LecturaCuerpo.Falla("La propiedad 'pregunta' no es un texto valido.");
        }

        if (string.IsNullOrWhiteSpace(pregunta))
        {
            return LecturaCuerpo.Falla("La propiedad 'pregunta' no puede estar vacia.");
        }

        if (pregunta.Length > MaxPregunta)
        {
            return LecturaCuerpo.Falla("La propiedad 'pregunta' supera la longitud maxima permitida.");
        }

        // Regla 4: usuario ausente o que no es un objeto.
        if (!tieneUsuario || usuario.ValueKind != JsonValueKind.Object)
        {
            return LecturaCuerpo.Falla("La propiedad 'usuario' es obligatoria y debe ser un objeto.");
        }

        // Regla 5 (la decide L1): rol/id ausente, null o de otro tipo -> null -> 403-identidad.
        var rol = LeerString(usuario, "rol");
        var id = LeerString(usuario, "id");
        return LecturaCuerpo.Ok(new PreguntarComando(pregunta, rol, id, requestId));
    }

    private static string? LeerString(JsonElement objeto, string nombre)
    {
        if (!objeto.TryGetProperty(nombre, out var el) || el.ValueKind != JsonValueKind.String)
        {
            return null;
        }

        try
        {
            return el.GetString();
        }
        catch (InvalidOperationException)
        {
            return null;
        }
    }

    /// <summary>Nombres comparados ya des-escapados y de forma Ordinal (<c>usuario</c> duplica <c>usuario</c>).</summary>
    private static bool TieneDuplicados(JsonElement objeto)
    {
        var vistos = new HashSet<string>(StringComparer.Ordinal);
        foreach (var propiedad in objeto.EnumerateObject())
        {
            if (!vistos.Add(propiedad.Name))
            {
                return true;
            }
        }

        return false;
    }

    private static bool EsContentTypeJson(string? contentType)
    {
        if (string.IsNullOrWhiteSpace(contentType) || !MediaTypeHeaderValue.TryParse(contentType, out var media))
        {
            return false;
        }

        return string.Equals(media.MediaType.Value, "application/json", StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>Lee hasta MaxBytes; devuelve null si el cuerpo es mayor.</summary>
    private static async Task<byte[]?> LeerAcotadoAsync(Stream body, CancellationToken ct)
    {
        using var ms = new MemoryStream();
        var buffer = new byte[8192];
        while (true)
        {
            var leidos = await body.ReadAsync(buffer, ct);
            if (leidos == 0)
            {
                return ms.ToArray();
            }

            if (ms.Length + leidos > MaxBytes)
            {
                return null;
            }

            ms.Write(buffer, 0, leidos);
        }
    }
}

