            [],
            new UsoTokens(entrada, salida));

    public static Func<LlmRequest, LlmResponse> Falla(Exception ex) => _ => throw ex;

    /// <summary>Todo lo que el LLM llega a ver en una solicitud (sistema, mensajes y herramientas).</summary>
